import{_ as t,d as a,e as n,y as i}from"./chunks/framework.D7CAgLCq.js";const p=JSON.parse('{"title":"A valid status and its consequences need different evidence","description":"Constitutive standing is established under applicable rules; causal effects concern what happens through it.","frontmatter":{"title":"A valid status and its consequences need different evidence","description":"Constitutive standing is established under applicable rules; causal effects concern what happens through it."},"headers":[],"relativePath":"en/concepts/status-and-effects.md","filePath":"en/concepts/status-and-effects.md"}'),s={name:"en/concepts/status-and-effects.md"};function r(o,e,d,l,c,h){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="a-valid-status-and-its-consequences-need-different-evidence" tabindex="-1">A valid status and its consequences need different evidence <a class="header-anchor" href="#a-valid-status-and-its-consequences-need-different-evidence" aria-label="Permalink to &quot;A valid status and its consequences need different evidence&quot;">​</a></h1><p><strong>Constitutive standing is established under applicable rules; causal effects concern what happens through it.</strong></p><p>Some relations constitute an office, right, membership, authorization, or promise under the rules of the relevant practice. Their standing is not inferred simply by observing that they produced an effect. A valid right may be obstructed in practice; actual influence can exist without valid authority.</p><p>Keep four inquiries visible: whether constitutive conditions hold, how participants understand the arrangement, whether it is implemented, and whether it is normatively justified. Documentary interpretation and causal inquiry may both matter, but answer different questions.</p><p>This prevents two opposite errors. Lack of an observed consequence does not automatically cancel an established right. A successful intervention does not retroactively supply a missing mandate or prove that a rule is just.</p><h2 id="keep-these-judgments-separate" tabindex="-1">Keep these judgments separate <a class="header-anchor" href="#keep-these-judgments-separate" aria-label="Permalink to &quot;Keep these judgments separate&quot;">​</a></h2><div class="xk-table"><table><thead><tr><th>Constitutive relation</th><th>Causal relation</th></tr></thead><tbody><tr><td>The applicable rules establish a specified standing.</td><td>A supported channel explains an actual effect.</td></tr></tbody></table></div><h2 id="teaching-example-an-approved-entitlement-and-a-delayed-payment" tabindex="-1">Teaching example: an approved entitlement and a delayed payment <a class="header-anchor" href="#teaching-example-an-approved-entitlement-and-a-delayed-payment" aria-label="Permalink to &quot;Teaching example: an approved entitlement and a delayed payment&quot;">​</a></h2><p>Assume a valid decision grants a benefit, but payment has not arrived. The entitlement may already exist; delivery remains incomplete. Whether the arrangement is fair requires a further argument.</p><p><strong>Assumptions:</strong> The validity of the decision is independently established; no real legal case is asserted.</p><p><strong>Boundary:</strong> The example does not determine any jurisdiction’s rules or authorize collection.</p><h2 id="check-your-reading" tabindex="-1">Check your reading <a class="header-anchor" href="#check-your-reading" aria-label="Permalink to &quot;Check your reading&quot;">​</a></h2><p><strong>If an unauthorized actor successfully solves a problem, has the success created authorization?</strong></p><p>No. Effectiveness does not supply the applicable constitutive conditions for authority.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><p>The framework does not invent the constitutive rules of a domain.</p></li><li><p>Legal validity and normative justification remain distinct.</p></li></ul><p>Read the complete <a href="/xi-kari-skill/handbook/en/theory/part-02.html#section-2-4-3">source section §2.4.3</a> and its guide. This explanation follows theory v2.1; the <a href="/xi-kari-skill/handbook/en/downloads.html">Chinese original</a> remains authoritative.</p>',17)])])}const f=t(s,[["render",r]]);export{p as __pageData,f as default};
